const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Cabo Frio region (Brazil)
  const caboFrio = ee.Geometry.Point([-42.03, -22.88]);
  const bufferZone = caboFrio.buffer(15000); // 15 km buffer to capture gradients

  // 2. Acquire SST data for September 2023
  const sstCollection = ee.ImageCollection('NOAA/CDR/SST_WHOI')
    .filterDate('2023-09-01', '2023-09-30')
    .filterBounds(bufferZone);

  const sstCount = sstCollection.size().getInfo();
  console.log(`September 2023 SST Images: ${sstCount}`);

  if (sstCount === 0) {
    // Try alternative SST dataset
    const altSst = ee.ImageCollection('MODIS/AQUA/MYD28M')
      .filterDate('2023-09-01', '2023-09-30')
      .filterBounds(bufferZone);

    const altCount = altSst.size().getInfo();
    console.log(`Alternative MODIS SST Images: ${altCount}`);

    if (altCount === 0) {
      console.log('No SST data found for September 2023 at Cabo Frio.');
      console.log('C1');
      return;
    }
  }

  // 3. Use MODIS Aqua SST (more reliable for coastal zones)
  const sst = ee.ImageCollection('MODIS/AQUA/MYD28M')
    .filterDate('2023-09-01', '2023-09-30')
    .filterBounds(bufferZone)
    .median(); // Composite for the month

  // 4. Check for valid pixels
  const validPixels = sst.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: bufferZone,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const pixelCount = validPixels['sst'] || 0;
  console.log(`Valid SST pixels: ${pixelCount}`);

  if (pixelCount === 0) {
    console.log('No valid SST pixels after processing.');
    console.log('C2');
    return;
  }

  // 5. Calculate temperature gradient
  // Using Sobel edge detection to find spatial gradients
  const sobelX = ee.Kernel.sobel();
  const gradX = sst.convolve(sobelX);
  const gradMag = gradX.abs();

  // Get maximum gradient within the zone
  const maxGradient = gradMag.reduceRegion({
    reducer: ee.Reducer.max(),
    geometry: bufferZone,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const gradient = maxGradient['sst'] || null;

  // Check temperature range (min-max as proxy for gradient)
  const tempStats = sst.reduceRegion({
    reducer: ee.Reducer.minMax(),
    geometry: bufferZone,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const minTemp = tempStats['sst_min'];
  const maxTemp = tempStats['sst_max'];

  if (minTemp === null || maxTemp === null || maxTemp === undefined || minTemp === undefined) {
    console.log('Invalid temperature values retrieved.');
    console.log('C3');
    return;
  }

  const tempRange = maxTemp - minTemp;
  console.log(`SST Range: ${minTemp.toFixed(2)}°C to ${maxTemp.toFixed(2)}°C`);
  console.log(`Temperature Gradient (Range): ${tempRange.toFixed(2)}°C`);
  console.log(`Max Spatial Gradient: ${gradient !== null ? gradient.toFixed(4) : 'N/A'}`);

  // 6. Interpretation: Gradient >5°C suggests sharp thermal fronts
  // Cabo Frio is known for upwelling, creating strong SST fronts
  if (tempRange > 5.0) {
    console.log('Temperature gradient >5°C detected within 10km zone.');
    console.log('A');
  } else {
    console.log('No temperature gradient >5°C within 10km zone.');
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
